import itertools
import json

def solve():
    houses = [0, 1, 2]  # indices 0..2 correspond to houses 1..3

    Names = ["Eric", "Peter", "Arnold"]
    Cigars = ["blue master", "prince", "pall mall"]
    Hobbies = ["photography", "gardening", "cooking"]
    Education = ["high school", "associate", "bachelor"]
    Drinks = ["tea", "milk", "water"]

    solution = None

    for names in itertools.permutations(Names):
        pos_name = {names[h]: h for h in houses}

        for cigars in itertools.permutations(Cigars):
            pos_cigar = {cigars[h]: h for h in houses}

            # Constraint 1: Pall Mall smoker is Peter
            if pos_cigar["pall mall"] != pos_name["Peter"]:
                continue

            # Constraint 4: Arnold and the Prince smoker are next to each other
            if abs(pos_name["Arnold"] - pos_cigar["prince"]) != 1:
                continue

            # Constraint 5: Gardening is somewhere to the left of the Prince smoker
            # This requires pos_hobby, so defer until hobbies loop, but we can ensure possible positions exist
            # We'll check fully in the hobbies loop.

            for hobbies in itertools.permutations(Hobbies):
                pos_hobby = {hobbies[h]: h for h in houses}

                # Constraint 5 check now
                if not (pos_hobby["gardening"] < pos_cigar["prince"]):
                    continue

                for education in itertools.permutations(Education):
                    pos_edu = {education[h]: h for h in houses}

                    # Constraint 7: Bachelor's is directly left of Photography
                    if pos_edu["bachelor"] + 1 != pos_hobby["photography"]:
                        continue

                    for drinks in itertools.permutations(Drinks):
                        pos_drink = {drinks[h]: h for h in houses}

                        # Constraint 2: Milk is directly left of High School
                        if not (pos_drink["milk"] + 1 == pos_edu["high school"]):
                            continue

                        # Constraint 6: Milk drinker is the Associate
                        if pos_drink["milk"] != pos_edu["associate"]:
                            continue

                        # Constraint 3: Eric is the tea drinker
                        if pos_name["Eric"] != pos_drink["tea"]:
                            continue

                        # If all constraints hold, we found the solution
                        rows = []
                        for h in houses:
                            row = [
                                str(h + 1),
                                names[h],
                                cigars[h],
                                hobbies[h],
                                education[h],
                                drinks[h],
                            ]
                            rows.append(row)

                        solution = {
                            "solution": {
                                "header": ["House", "Name", "Cigar", "Hobby", "Education", "Drink"],
                                "rows": rows,
                            }
                        }
                        return solution

    return None

def main():
    result = solve()
    if result is None:
        print(json.dumps({"solution": {"header": ["House", "Name", "Cigar", "Hobby", "Education", "Drink"], "rows": []}}))
    else:
        print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    main()
